SET client_encoding = 'UTF8';

SET standard_conforming_strings = on;

SET lock_timeout = '10s';

LOCK TABLE public.ingredients, public.recipes, public.recipe_ingredients, public.recipe_steps, public.recipe_scraps, public.pantry_items, public.cooking_histories IN ACCESS EXCLUSIVE MODE;

DO $$ BEGIN IF EXISTS (SELECT 1 FROM public.recipe_scraps) THEN RAISE EXCEPTION 'recipe_scraps contains user data'; END IF; END $$;

DO $$ BEGIN IF EXISTS (SELECT 1 FROM public.pantry_items) THEN RAISE EXCEPTION 'pantry_items contains user data'; END IF; END $$;

DO $$ BEGIN IF EXISTS (SELECT 1 FROM public.cooking_histories) THEN RAISE EXCEPTION 'cooking_histories contains user data'; END IF; END $$;

DELETE FROM public.recipe_ingredients;

DELETE FROM public.recipe_steps;

DELETE FROM public.recipes;

DELETE FROM public.ingredients;





DO $$ BEGIN IF (SELECT count(*) FROM public.ingredients) <> 148 THEN RAISE EXCEPTION 'ingredients count mismatch'; END IF; END $$;

DO $$ BEGIN IF (SELECT count(*) FROM public.recipes) <> 7776 THEN RAISE EXCEPTION 'recipes count mismatch'; END IF; END $$;

DO $$ BEGIN IF (SELECT count(*) FROM public.recipe_ingredients) <> 73297 THEN RAISE EXCEPTION 'recipe_ingredients count mismatch'; END IF; END $$;

DO $$ BEGIN IF (SELECT count(*) FROM public.recipe_steps) <> 64313 THEN RAISE EXCEPTION 'recipe_steps count mismatch'; END IF; END $$;
